// Tests for scripts/gate-conformance.mjs. Run with: node --test scripts/gate-conformance.test.mjs
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { conformanceCoverage, conformanceVerdict, routedShipped, skippedList, stringList } from './gate-conformance.mjs';

// As rustfmt writes the generated file.
const GENERATED = `// @generated by specc from specifications/spec.jsonc. Do not edit; change the specification and regenerate.
use crate::harness::*;

/// Every contract with a test here.
pub const COVERED: &[&str] = &[
    "sign-in-at-site",
    "assign-role",
];

/// The checks that are not made: (contract, check, reason).
pub const SKIPPED: &[(&str, &str, &str)] = &[
    (
        "assign-role",
        "success",
        "it has required inputs and no conformanceExample",
    ),
    ("sign-in-at-site", "quota", "its limit 100 is \\"above\\" the 99 calls the suite makes"),
];
`;

const CONTRACTS = [
  { id: 'sign-in-at-site', deployment: 'shipped', bffRoute: 'POST /api/login' },
  { id: 'assign-role', deployment: 'shipped', bffRoute: 'POST /api/members/assign-role' },
  { id: 'internal-only', deployment: 'shipped' },
  { id: 'later', deployment: 'target', bffRoute: 'GET /api/later' },
];

test('the lists are read from the generated text', () => {
  assert.deepEqual(stringList(GENERATED, 'COVERED'), ['sign-in-at-site', 'assign-role']);
  assert.deepEqual(skippedList(GENERATED), [
    { contract: 'assign-role', check: 'success', reason: 'it has required inputs and no conformanceExample' },
    { contract: 'sign-in-at-site', check: 'quota', reason: 'its limit 100 is "above" the 99 calls the suite makes' },
  ]);
  assert.equal(stringList('fn main() {}', 'COVERED'), null);
  assert.deepEqual(routedShipped(CONTRACTS), ['sign-in-at-site', 'assign-role']);
});

test('a covered suite passes and counts what it does not check', () => {
  const verdict = conformanceVerdict(conformanceCoverage({ contracts: CONTRACTS, generated: GENERATED }));
  assert.equal(verdict.ok, true, verdict.lines.join('\n'));
  assert.match(verdict.detail, /^2 of 2 covered; 2 checks not made \(quota 1, success 1\)$/);
  assert.equal(verdict.lines.filter((l) => l.startsWith('not checked: ')).length, 2);
});

test('a shipped contract with a route and no test fails, and so does a stale test', () => {
  const more = [...CONTRACTS, { id: 'revoke-role', deployment: 'shipped', bffRoute: 'POST /api/members/revoke-role' }];
  const missing = conformanceVerdict(conformanceCoverage({ contracts: more, generated: GENERATED }));
  assert.equal(missing.ok, false);
  assert.ok(missing.lines.includes('missing: revoke-role'));
  const fewer = CONTRACTS.filter((c) => c.id !== 'assign-role');
  const stale = conformanceVerdict(conformanceCoverage({ contracts: fewer, generated: GENERATED }));
  assert.equal(stale.ok, false);
  assert.ok(stale.lines.includes('stale (no longer shipped with a route): assign-role'));
});

test('a missing or unreadable suite fails', () => {
  const absent = conformanceVerdict(conformanceCoverage({ contracts: CONTRACTS, generated: null }));
  assert.equal(absent.ok, false);
  assert.match(absent.lines[0], /does not exist/);
  const broken = conformanceVerdict(conformanceCoverage({ contracts: CONTRACTS, generated: 'pub const COVERED: &[&str] = &["a"];' }));
  assert.equal(broken.ok, false);
});
